package games.brennan.dungeontrain.client;

import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Pins the two gates that decide whether {@link RunWorldCleanup} may delete a save folder: the
 * auto-generated name and the dead saved player. Each false case is a world that must survive.
 */
class RunWorldCleanupTest {

    @Test
    @DisplayName("auto-generated run world names match")
    void autoNamesMatch() {
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("World 1791741323610"));
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("Dungeon Train 1791666517688"));
        assertTrue(RunWorldCleanup.isAutoGeneratedWorldName("Dev World 1791666517688"));
    }

    @Test
    @DisplayName("hand-made, empty-suffix and editor world names never match")
    void otherNamesDoNotMatch() {
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World of Pain"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World "));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("World 123 copy"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("train editor 3"));
        assertFalse(RunWorldCleanup.isAutoGeneratedWorldName("New World"));
    }

    @Test
    @DisplayName("a saved player with no health is a dead run")
    void deadPlayerIsDeadRun() {
        assertTrue(RunWorldCleanup.isDeadRun(levelDatWithHealth(0.0F)));
    }

    @Test
    @DisplayName("a living saved player keeps the world")
    void livePlayerKeepsWorld() {
        assertFalse(RunWorldCleanup.isDeadRun(levelDatWithHealth(20.0F)));
        assertFalse(RunWorldCleanup.isDeadRun(levelDatWithHealth(0.5F)));
    }

    @Test
    @DisplayName("missing player or health data keeps the world")
    void missingDataKeepsWorld() {
        assertFalse(RunWorldCleanup.isDeadRun(new CompoundTag()));
        CompoundTag noPlayer = new CompoundTag();
        noPlayer.put("Data", new CompoundTag());
        assertFalse(RunWorldCleanup.isDeadRun(noPlayer));
        CompoundTag noHealth = new CompoundTag();
        CompoundTag data = new CompoundTag();
        data.put("Player", new CompoundTag());
        noHealth.put("Data", data);
        assertFalse(RunWorldCleanup.isDeadRun(noHealth));
    }

    private static CompoundTag levelDatWithHealth(float health) {
        CompoundTag player = new CompoundTag();
        player.putFloat("Health", health);
        CompoundTag data = new CompoundTag();
        data.put("Player", player);
        CompoundTag root = new CompoundTag();
        root.put("Data", data);
        return root;
    }
}
